-- GenDB engine variant Q20-conjunct_permutation: template q20.sql, kind conjunct_permutation (generated by generate.py; frozen)
SELECT
  s_name,
  s_address
FROM supplier, nation
WHERE
  n_name = $3
  AND s_nationkey = n_nationkey
  AND s_suppkey IN (
    SELECT
      ps_suppkey
    FROM partsupp
    WHERE
      ps_partkey IN (
        SELECT
          p_partkey
        FROM part
        WHERE
          p_name LIKE $1
      )
      AND ps_availqty > (
        SELECT
          0.5 * SUM(l_quantity)
        FROM lineitem
        WHERE
          l_shipdate < $2 + INTERVAL '1 YEAR'
          AND l_shipdate >= $2
          AND l_suppkey = ps_suppkey
          AND l_partkey = ps_partkey
      )
  )
ORDER BY
  s_name
